using System.Net.Http.Headers;
using System.Text.Json;
var builder=WebApplication.CreateBuilder(args);builder.Services.AddHttpClient("azure",c=>c.Timeout=TimeSpan.FromMinutes(3));var app=builder.Build();
app.MapGet("/health/live",()=>Results.Ok(new{status="ok"}));
app.MapPost("/internal/extractions",async(HttpRequest req,IHttpClientFactory factory,IConfiguration cfg,CancellationToken ct)=>{
 var expected=cfg["Internal:Key"]??"local-placeholder";if(!req.Headers.TryGetValue("X-Internal-Key",out var supplied)||!System.Security.Cryptography.CryptographicOperations.FixedTimeEquals(System.Text.Encoding.UTF8.GetBytes(expected),System.Text.Encoding.UTF8.GetBytes(supplied.ToString())))return Results.Unauthorized();
 var form=await req.ReadFormAsync(ct);var file=form.Files.GetFile("file");if(file is null||file.Length==0)return Results.BadRequest(new{error="Missing file."});var endpoint=cfg["ContentUnderstanding:Endpoint"];var key=cfg["ContentUnderstanding:ApiKey"];if(string.IsNullOrWhiteSpace(endpoint)||string.IsNullOrWhiteSpace(key)||key.StartsWith("replace-",StringComparison.OrdinalIgnoreCase))return Results.Problem("Content Understanding is not configured.",statusCode:503);
 var http=factory.CreateClient("azure");var analyzer=cfg["ContentUnderstanding:Analyzer"]??"prebuilt-documentSearch";using var content=new StreamContent(file.OpenReadStream());content.Headers.ContentType=new MediaTypeHeaderValue("application/octet-stream");using var request=new HttpRequestMessage(HttpMethod.Post,$"{endpoint.TrimEnd('/')}/contentunderstanding/analyzers/{Uri.EscapeDataString(analyzer)}:analyzeBinary?api-version=2025-11-01");request.Headers.Add("Ocp-Apim-Subscription-Key",key);request.Content=content;using var response=await http.SendAsync(request,ct);if((int)response.StatusCode!=202&&!response.IsSuccessStatusCode)return Results.Problem("Content Understanding rejected the document. Check analyzer and resource configuration.",statusCode:503);if(!response.Headers.TryGetValues("Operation-Location",out var locations))return Results.Problem("Content Understanding did not return an operation URL.",statusCode:503);var operation=locations.Single();var root=new Uri(endpoint);if(!Uri.TryCreate(operation,UriKind.Absolute,out var opUri)||opUri.Host!=root.Host)return Results.Problem("Content Understanding returned an invalid operation URL.",statusCode:502);
 for(var attempt=0;attempt<60;attempt++){await Task.Delay(TimeSpan.FromSeconds(2),ct);using var poll=new HttpRequestMessage(HttpMethod.Get,opUri);poll.Headers.Add("Ocp-Apim-Subscription-Key",key);using var result=await http.SendAsync(poll,ct);if(!result.IsSuccessStatusCode)return Results.Problem("Content Understanding extraction polling failed.",statusCode:503);using var json=await JsonDocument.ParseAsync(await result.Content.ReadAsStreamAsync(ct),cancellationToken:ct);var state=json.RootElement.TryGetProperty("status",out var status)?status.GetString():"";if(state is "Failed" or "Canceled")return Results.Problem("Content Understanding could not extract this document.",statusCode:422);if(state is "Succeeded" or "Completed"){var text=ExtractText(json.RootElement);return Results.Ok(new{text});}}
 return Results.Problem("Content Understanding extraction timed out. Retry the document.",statusCode:504);
});await app.RunAsync();
static string ExtractText(JsonElement root){var output=new List<string>();void Walk(JsonElement e){if(e.ValueKind==JsonValueKind.Object){foreach(var p in e.EnumerateObject()){if(p.Name.Equals("markdown",StringComparison.OrdinalIgnoreCase)||p.Name.Equals("text",StringComparison.OrdinalIgnoreCase)){if(p.Value.ValueKind==JsonValueKind.String){var s=p.Value.GetString();if(!string.IsNullOrWhiteSpace(s))output.Add(s!);}}else Walk(p.Value);}}else if(e.ValueKind==JsonValueKind.Array)foreach(var x in e.EnumerateArray())Walk(x);}Walk(root);return string.Join("\n\n",output.Distinct());}
